```php
class Queue {
    private $queue;

    public function __construct() {
        $this->queue = [];
    }

    /**
     * Enqueue the value to the end of a Queue.
     * 
     * @param mixed $value
     * @return void    Adds a new  value to the end of a Queue.
     */
    public function enqueue($value) {
        array_unshift($this->queue, $value);
    }

    /**
     * Dequeue the value to the end of a Queue.
     * 
     * @return mixed    Remove the value in a Queue and return the value in, all items in a Queue will reduce by 1.
     */
    public function dequeue() {
        if (!empty($this->queue)) {
            return (array_shift($this->queue));
        }

        return (null);
    }

    /**
     * Peek the value in a Queue.
     * 
     * @return mixed    Return the value in, all items in a Queue will reduce by 1.
     */
    public function peek() {
        return (count($this->queue) > 0) ? end($this->queue) : null;
    }

    /**
     * Check if is empty of a Queue.
     *
     * @return bool    True if is empty, otherwise, false as soon
     */
    public function isEmpty() {
        return (count($this->queue) === 0);
    }

    /**
     * Get the size of a Queue.
     *
     * @return int Count how many items in a Queue.
     */
    public function getSize() {
        return (count($this->queue));
    }
}

// Example usage to create and manipulate a Queue
$queue = new Queue();

echo $queue->enqueue(1); // outputs: 1
echo $queue->enqueue(2); // outputs: 1,2
echo $queue->enqueue(3); // outputs: 1,2,3

echo "Dequeued: " . $queue->dequeue(); // outputs: 1

echo "Peek: " . $queue->peek(); // outputs: 2

echo "Is empty: " . ($queue->isEmpty() ? "True" : "False"); // outputs: False

echo "Size: " . $queue->getSize(); // outputs: 2

// Re-insert the value to the end of a Queue
$queue->enqueue(4);

echo "Re-dequeued: " . $queue->dequeue(); // outputs: 2

echo "Peek: " . $queue->peek(); // outputs: 3
```

