// Function to determine whether a character is in a string of vowels
func isVowel(character: Character) -> Bool {
    let vowels = CharacterSet.letters.inverted.union(["ü", "ö", "ä", "ß"]) // Include special vowels and 'ß'
    return vowels.contains(character)
}

// Function to input and output vowels from inputted string by the user
func extractVowelsFromUserInput() {
    print("\(User Input): ")

    // Read userinput
    if let userInput = readLine() {
        // Check if inputted string is nonempty
        guard userInput.count > 0 else return      

        // Collect vowels from inputted string in a new, empty, string for each vowel found within it. 
        let result = userInput.filter { isVowel(character: $0) }
        print("\(User Input): \(result)")
    }
}

// Call the function to begin operation (User Input from here: )
extractVowelsFromUserInput()
